"""Tests for the ``xrlenv bootstrap`` subcommand (B8.1, P1.x slice 5).

Three coverage axes:

1. **OS detection** — ``detect_os`` correctly parses
   ``/etc/os-release`` content and maps to the package-manager
   family. Override path works when the file is missing.

2. **Config + plan construction** — ``build_config`` resolves
   operator inputs + env vars into a typed config; ``build_plan``
   emits the right step sequence for each (target, os_family)
   combination. No actual subprocess calls.

3. **Dry-run runner** — ``run_plan`` in dry-run mode emits the
   step names + descriptions + the commands that would run, and
   never invokes the subprocess for ``commands`` or runs the
   ``python_fn`` callbacks. Idempotent ``skip_if`` predicates can
   short-circuit individual steps.

We deliberately do *not* test the live-mode side effects (apt
install, useradd, etc.) — those need a real Linux VM. The
operator-driven smoke test covers that surface tomorrow.
"""

from __future__ import annotations

import io
from pathlib import Path
from typing import Any

import pytest
from xrlenv.cli.bootstrap import (
    Step,
    _parse_os_release,
    build_config,
    build_plan,
    detect_os,
    run_plan,
)

# ──────────────────────────────────────────────────────────────────────────────
# detect_os + _parse_os_release
# ──────────────────────────────────────────────────────────────────────────────


def test_parse_os_release_strips_quotes_and_comments() -> None:
    body = """
# Generated by systemd
NAME="Ubuntu"
VERSION_ID="22.04"
ID=ubuntu
VERSION_CODENAME=jammy
"""
    out = _parse_os_release(body)
    assert out["NAME"] == "Ubuntu"
    assert out["VERSION_ID"] == "22.04"
    assert out["ID"] == "ubuntu"
    assert out["VERSION_CODENAME"] == "jammy"


def test_detect_os_with_override_skips_filesystem() -> None:
    """``--target-os`` lets the operator bypass /etc/os-release when
    it's missing or wrong (custom AMIs)."""
    info = detect_os("ubuntu")
    assert info.id == "ubuntu"
    assert info.family == "debian"


def test_detect_os_maps_rhel_family_correctly() -> None:
    for rhel_id in ("amzn", "rhel", "fedora", "centos", "rocky", "almalinux"):
        info = detect_os(rhel_id)
        assert info.family == "rhel", f"{rhel_id!r} should be rhel-family"


def test_detect_os_maps_debian_family_correctly() -> None:
    for deb_id in ("ubuntu", "debian"):
        info = detect_os(deb_id)
        assert info.family == "debian", f"{deb_id!r} should be debian-family"


def test_detect_os_refuses_unknown_distro() -> None:
    with pytest.raises(RuntimeError, match="unsupported OS"):
        detect_os("arch")


# ──────────────────────────────────────────────────────────────────────────────
# build_config — env-var + operator-flag resolution
# ──────────────────────────────────────────────────────────────────────────────


def _ok_env(**overrides: str) -> dict[str, str]:
    base = {
        "XRLENV_CONTROL_PLANE": "10.0.0.1:50051",
        "XRLENV_NODE_ID": "test-node-1",
    }
    base.update(overrides)
    return base


def test_build_config_pulls_from_env_when_flags_omitted() -> None:
    config = build_config(
        target="linux-generic",
        control_plane=None,
        node_id=None,
        target_os="ubuntu",
        xrlenv_wheel=None,
        xrlenv_repo=None,
        xrlenv_version=None,
        runtime_user=None,
        install_root=None,
        skip_operator_docker_group=False,
        env=_ok_env(),
    )
    assert config.control_plane == "10.0.0.1:50051"
    assert config.node_id == "test-node-1"
    assert config.xrlenv_version == "main"  # falls back to "main".


def test_build_config_flags_override_env() -> None:
    config = build_config(
        target="linux-generic",
        control_plane="control:443",
        node_id="explicit-id",
        target_os="ubuntu",
        xrlenv_wheel=None,
        xrlenv_repo=None,
        xrlenv_version="0.1.2",
        runtime_user=None,
        install_root=None,
        skip_operator_docker_group=False,
        env=_ok_env(XRLENV_CONTROL_PLANE="env-val", XRLENV_VERSION="env-ver"),
    )
    assert config.control_plane == "control:443"
    assert config.node_id == "explicit-id"
    assert config.xrlenv_version == "0.1.2"


