def test_build_config_picks_up_sudo_user() -> None:
    """SUDO_USER → config.operator_user. Drives the docker-group add."""
    config = build_config(
        target="linux-generic",
        control_plane="cp:1",
        node_id="x",
        target_os="ubuntu",
        xrlenv_wheel=None,
        xrlenv_repo=None,
        xrlenv_version=None,
        runtime_user=None,
        install_root=None,
        skip_operator_docker_group=False,
        env=_ok_env(SUDO_USER="alice"),
    )
    assert config.operator_user == "alice"


# ──────────────────────────────────────────────────────────────────────────────
# build_plan — step ordering + per-target branches
# ──────────────────────────────────────────────────────────────────────────────


def _config(**overrides: Any) -> Any:
    defaults: dict[str, Any] = {
        "target": "linux-generic",
        "control_plane": "cp:1",
        "node_id": "x",
        "target_os": "ubuntu",
        "xrlenv_wheel": None,
        "xrlenv_repo": None,
        "xrlenv_version": None,
        "runtime_user": None,
        "install_root": None,
        "skip_operator_docker_group": False,
    }
    defaults.update({k: v for k, v in overrides.items() if k in defaults})
    env = _ok_env()
    if "operator_user" in overrides:
        env["SUDO_USER"] = overrides["operator_user"]
    if "node_token" in overrides:
        env["XRLENV_NODE_TOKEN"] = overrides["node_token"]
    if "dockerhub_user" in overrides:
        env["DOCKERHUB_USER"] = overrides["dockerhub_user"]
    if "dockerhub_token" in overrides:
        env["DOCKERHUB_TOKEN"] = overrides["dockerhub_token"]
    return build_config(env=env, **defaults)


def test_build_plan_includes_token_dropin_only_when_token_set() -> None:
    plan_no_tok = build_plan(_config())
    assert not any(
        s.name == "install-node-token-dropin" for s in plan_no_tok
    )
    plan_tok = build_plan(_config(node_token="t1"))
    assert any(s.name == "install-node-token-dropin" for s in plan_tok)


def test_build_plan_includes_dockerhub_auth_only_when_both_creds_set() -> None:
    """Install step only fires when BOTH DOCKERHUB_USER and
    DOCKERHUB_TOKEN are present. Half-set creds → skip the install
    (the warning step still surfaces the gap at plan tail)."""
    plan_none = build_plan(_config())
    assert not any(
        s.name == "install-dockerhub-auth" for s in plan_none
    )

    plan_user_only = build_plan(_config(dockerhub_user="alice"))
    assert not any(
        s.name == "install-dockerhub-auth" for s in plan_user_only
    )

    plan_token_only = build_plan(_config(dockerhub_token="dckr_pat_x"))
    assert not any(
        s.name == "install-dockerhub-auth" for s in plan_token_only
    )

    plan_both = build_plan(_config(
        dockerhub_user="alice", dockerhub_token="dckr_pat_x",
    ))
    assert any(s.name == "install-dockerhub-auth" for s in plan_both)


def test_build_plan_always_includes_dockerhub_warning_step() -> None:
    """The advisory warning step is always in the plan; it self-
    short-circuits at runtime when a config.json is in place. Always-
    on means operators see the rate-limit gap on first bootstrap
    rather than via a downstream failure 30 minutes later."""
    plan_none = build_plan(_config())
    plan_creds = build_plan(_config(
        dockerhub_user="alice", dockerhub_token="dckr_pat_x",
    ))
    assert any(s.name == "warn-no-dockerhub-auth" for s in plan_none)
    assert any(s.name == "warn-no-dockerhub-auth" for s in plan_creds)
    # Warning step must come AFTER the install step so a successful
    # install in the same plan suppresses the warning at runtime via
    # the config.json existence check.
    names_creds = [s.name for s in plan_creds]
    assert (
        names_creds.index("install-dockerhub-auth")
        < names_creds.index("warn-no-dockerhub-auth")
    )


def test_build_plan_writes_dockerhub_auth_before_node_daemon_restart() -> None:
    """Audit M1 (2026-05-12): the docker-py ``APIClient.__init__``
    reads ``~/.docker/config.json`` ONCE at construction and caches
    the auth dict. If the auth file lands after the xrlenv-node
    daemon has started, the daemon's already-constructed
    ``DockerBackend`` keeps an empty-auth cache and every pull stays
    unauthenticated until the next restart. The Python plan must
    write the auth file BEFORE the daemon's systemctl restart.

    (The legacy bash wrapper's same invariant is asserted in
    ``tests/unit/deploy/test_bootstrap_dockerhub_auth.py::
    test_bootstrap_xrlenv_installs_auth_before_systemd_unit``.)
    """
    plan = build_plan(_config(
        dockerhub_user="alice", dockerhub_token="dckr_pat_x",
    ))
    names = [s.name for s in plan]
    assert "install-dockerhub-auth" in names
    assert "systemctl-restart-xrlenv-node" in names
    assert (
        names.index("install-dockerhub-auth")
        < names.index("systemctl-restart-xrlenv-node")
    ), (
        "install-dockerhub-auth must run BEFORE "
        "systemctl-restart-xrlenv-node so docker-py picks up the "
        "config.json at daemon-process startup."
    )


def test_build_plan_includes_operator_docker_group_only_when_sudo_user_set() -> None:
    plan_no_op = build_plan(_config())
    assert not any(
        s.name == "ensure-operator-docker-group" for s in plan_no_op
    )
    plan_op = build_plan(_config(operator_user="alice"))
    assert any(s.name == "ensure-operator-docker-group" for s in plan_op)


def test_build_plan_skips_operator_docker_group_when_opt_out() -> None:
    """``--skip-operator-docker-group`` wins even if SUDO_USER is set."""
    plan = build_plan(_config(
        operator_user="alice", skip_operator_docker_group=True,
    ))
    assert not any(
        s.name == "ensure-operator-docker-group" for s in plan
    )


def test_build_plan_gcp_uses_upstream_docker_apt_repo() -> None:
    """--target gcp on Debian/Ubuntu always uses the upstream Docker
    apt repo (the in-process Python step), not the simpler
    ``apt install docker.io`` path."""
    plan = build_plan(_config(target="gcp"))
    names = [s.name for s in plan]
    assert "install-docker-apt-key-and-repo" in names
    assert "apt-install-docker" not in names


def test_build_plan_aws_rhel_uses_dnf() -> None:
    plan = build_plan(_config(target="aws", target_os="amzn"))
    names = [s.name for s in plan]
    assert "dnf-install-docker" in names
    assert "apt-install-docker" not in names
    assert "install-docker-apt-key-and-repo" not in names


def test_build_plan_pip_source_priority_wheel_over_repo_over_pypi(
    tmp_path: Path,
) -> None:
    """When --xrlenv-wheel is set, the plan installs from that wheel
    (not from --xrlenv-repo or PyPI)."""
    wheel = tmp_path / "xrlenv-0.0.1-py3-none-any.whl"
    wheel.write_text("not a real wheel — content not consulted")
    repo = tmp_path / "checkout"
    repo.mkdir()
    (repo / "pyproject.toml").write_text("[project]\nname='xrlenv'\n")
    plan = build_plan(_config(xrlenv_wheel=wheel, xrlenv_repo=repo))
    pip_step = next(s for s in plan if s.name == "pip-install-xrlenv")
    install_cmd = pip_step.commands[1]
    assert str(wheel) in install_cmd
    assert str(repo) not in install_cmd


# ──────────────────────────────────────────────────────────────────────────────
# run_plan — dry-run behaviour
# ──────────────────────────────────────────────────────────────────────────────


def test_run_plan_dry_run_prints_each_step_and_command() -> None:
    plan = [
        Step(
            name="hello",
            description="say hello",
            commands=[["echo", "hi"]],
        ),
        Step(
            name="world",
            description="say world",
            commands=[["echo", "world"]],
        ),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=True, out=out)
    assert rc == 0
    body = out.getvalue()
    assert "hello" in body
    assert "say hello" in body
    assert "DRY: echo hi" in body
    assert "DRY: echo world" in body
    assert "[xrlenv bootstrap — DRY-RUN]" in body


def test_run_plan_dry_run_honors_skip_predicate() -> None:
    """A step whose ``skip_if`` returns True shows up as skipped and
    its commands are not printed even in dry-run."""
    plan = [
        Step(
            name="installed-already",
            description="install x",
            commands=[["pretend-install", "x"]],
            skip_if=lambda: True,
        ),
        Step(
            name="missing",
            description="install y",
            commands=[["pretend-install", "y"]],
            skip_if=lambda: False,
        ),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=True, out=out)
    assert rc == 0
    body = out.getvalue()
    assert "installed-already" in body
    assert "(skipped — already done)" in body
    assert "DRY: pretend-install x" not in body
    assert "DRY: pretend-install y" in body


def test_run_plan_dry_run_does_not_execute_python_fn() -> None:
    """Even a step's in-process ``python_fn`` is suppressed in dry-run."""
    called: list[str] = []
    plan = [
        Step(
            name="dangerous",
            description="would destroy stuff",
            python_fn=lambda: called.append("ran"),
        ),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=True, out=out)
    assert rc == 0
    assert called == []  # python_fn must NOT have run.
    assert "in-process Python step" in out.getvalue()


def test_run_plan_live_propagates_python_fn_failure() -> None:
    """Live mode runs the python_fn; an exception is surfaced as a
    non-zero exit, never silently swallowed."""
    def boom() -> None:
        raise RuntimeError("xrlenv-node not on venv PATH")
    plan = [
        Step(name="verify", description="verify install", python_fn=boom),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=False, out=out)
    assert rc == 1
    assert "xrlenv-node not on venv PATH" in out.getvalue()


def test_run_plan_allow_failure_continues_on_failed_command() -> None:
    """``allow_failure=True`` lets the plan continue past a step
    whose subprocess returned non-zero. Critical for the
    ``apt-install-python312`` step on Ubuntu 22.04 / Debian where
    the package isn't in apt — the next step (uv fallback) must
    still run."""
    plan = [
        Step(
            name="expected-fail",
            description="install thing that may not be in the repo",
            commands=[["false"]],  # always exits 1.
            allow_failure=True,
        ),
        Step(
            name="follow-up",
            description="picks up the slack",
            commands=[["true"]],
        ),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=False, out=out)
    assert rc == 0  # plan still succeeds.
    body = out.getvalue()
    assert "SOFT-FAIL (allowed)" in body
    assert "follow-up" in body
    assert "OK" in body


def test_run_plan_allow_failure_continues_on_failed_python_fn() -> None:
    """allow_failure also covers python_fn exceptions — same
    contract for the rare step that wraps a Python helper."""
    def boom() -> None:
        raise RuntimeError("oops")
    plan = [
        Step(
            name="soft-fail-py",
            description="python fn that throws",
            python_fn=boom,
            allow_failure=True,
        ),
    ]
    out = io.StringIO()
    rc = run_plan(plan, dry_run=False, out=out)
    assert rc == 0
    assert "SOFT-FAIL (allowed): oops" in out.getvalue()


def test_build_plan_marks_python_install_as_allow_failure() -> None:
    """B8.1 audit response Q1: the apt-install-python312 /
    dnf-install-python312 steps must be allow_failure so a missing
    distro package doesn't kill the bootstrap before the uv
    fallback runs."""
    deb_plan = build_plan(_config(target_os="ubuntu"))
    apt_step = next(
        s for s in deb_plan if s.name == "apt-install-python312"
    )
    assert apt_step.allow_failure is True
    rhel_plan = build_plan(_config(target_os="amzn"))
    dnf_step = next(
        s for s in rhel_plan if s.name == "dnf-install-python312"
    )
    assert dnf_step.allow_failure is True


def test_build_plan_create_venv_uses_python_fn_not_hardcoded_binary() -> None:
    """B8.1 audit response Q2: the create-venv step must use a
    ``python_fn`` (which resolves the interpreter at runtime via
    XRLENV_PYTHON / PATH / uv-install dir), not a hardcoded
    ``python3.12 -m venv`` command. Otherwise the uv-managed
    interpreter — which lands outside PATH — would never be used
    even after the fallback ran successfully."""
    plan = build_plan(_config())
    venv_step = next(s for s in plan if s.name == "create-venv")
    assert venv_step.python_fn is not None
    assert venv_step.commands == []  # not a subprocess call.
